#include <iostream>
class Capacity {
    int limit_;
public:
    explicit Capacity(int limit) : limit_(limit > 0 ? limit : 1) {}
    int limit() const { return limit_; }
};
int main() {
    Capacity limit(8);
    std::cout << limit.limit() << std::endl;
}
